class Document {
    var text = ""

    func save() throws {
        // write `text` to disk
    }
}

final class SharedDocument: Document {
    override func save() throws {
        fatalError("Shared documents are read-only")
    }
}

func autosave(_ documents: [Document]) {
    for document in documents {
        try? document.save()
    }
}
